    #[test]
    fn gpu_f64_stockham_matches_cpu_or_skips_without_float64() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let profile = context.device_profile();
        if !profile.supports_f64 {
            return;
        }
        for length in [4usize, 5, 7, 9, 10, 12, 15, 16, 21, 26, 30, 35, 42, 49, 70] {
            let plan =
                FftPlan::build(FftConfig::new(vec![length]).with_precision(crate::Precision::F64))
                    .unwrap();
            let ir = KernelIr::stockham_1d(&plan, Direction::Forward, profile).unwrap();
            if profile.vendor == GpuVendor::Nvidia
                && matches!(
                    length,
                    5 | 7 | 9 | 10 | 12 | 15 | 21 | 26 | 30 | 35 | 42 | 49 | 70
                )
            {
                assert!(ir.scheduler_hint.is_some());
                assert_eq!(
                    ir.execution_layout,
                    crate::StockhamExecutionLayout::RegisterSingleShared
                );
            }
            let shader = VulkanGlslBackend
                .lower(&ir)
                .unwrap()
                .compile_spirv()
                .unwrap();
            let input = (0..length)
                .map(|index| {
                    let x = index as f64;
                    Complex64::new((0.13 * x).sin() + x * 0.001, (0.07 * x).cos() - x * 0.0004)
                })
                .collect::<Vec<_>>();
            let actual = context.execute_complex64(&shader, &input).unwrap();
            let expected = crate::reference::dft(&input, Direction::Forward, false);
            let max_error = actual
                .iter()
                .zip(&expected)
                .map(|(actual, expected)| (*actual - *expected).norm_sqr().sqrt())
                .fold(0.0, f64::max);
            assert!(
                max_error <= 2.0e-10 * length as f64,
                "F64 Stockham mismatch on {} at length {length}: max_error={max_error:e}",
                context.device_name()
            );
        }
    }

    #[test]
    fn gpu_double_double_stockham_preserves_residual_and_f64_storage_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        if !context.device_profile().supports_f64 {
            return;
        }

        let copy_plan =
            FftPlan::build(FftConfig::new(vec![1]).with_precision(Precision::DoubleDouble))
                .unwrap();
        let copy_ir = crate::DoubleDoubleStockhamIr::build(&copy_plan, Direction::Forward).unwrap();
        let copy_input = vec![crate::ComplexDoubleDouble::new(
            crate::DoubleDouble::from_parts(1.0e16, 1.0),
            crate::DoubleDouble::from_parts(-3.0, 0.25),
        )];
        let copy_output = context
            .execute_double_double_stockham(&copy_ir, &copy_input)
            .unwrap();
        assert_eq!(
            copy_output,
            copy_input,
            "Vulkan DD storage-only copy changed hi/lo words on {}",
            context.device_name()
        );

        let length = 4usize;
        let forward_plan =
            FftPlan::build(FftConfig::new(vec![length]).with_precision(Precision::DoubleDouble))
                .unwrap();
        let inverse_plan = FftPlan::build(
            FftConfig::new(vec![length])
                .with_precision(Precision::DoubleDouble)
                .with_inverse_normalization(true),
        )
        .unwrap();
        let forward =
            crate::DoubleDoubleStockhamIr::build(&forward_plan, Direction::Forward).unwrap();
        let inverse =
            crate::DoubleDoubleStockhamIr::build(&inverse_plan, Direction::Inverse).unwrap();
        let base = crate::DoubleDouble::from_f64(1.0e16);
        let mut input =
            vec![crate::ComplexDoubleDouble::new(base, crate::DoubleDouble::ZERO); length];
        input[0].re += crate::DoubleDouble::ONE;
        let spectrum = context
            .execute_double_double_stockham(&forward, &input)
            .unwrap();
        let dc_offset = spectrum[0].re - crate::DoubleDouble::from_f64(4.0e16);
        assert!(
            (dc_offset - crate::DoubleDouble::ONE).abs().to_f64().abs() <= 1.0e-28,
            "Vulkan DD DC residual was lost on {}: {dc_offset:?}",
            context.device_name()
        );
        for bin in spectrum.iter().skip(1) {
            assert!(
                (bin.re - crate::DoubleDouble::ONE).abs().to_f64().abs() <= 1.0e-28,
                "Vulkan DD non-DC residual mismatch on {}: {bin:?}",
                context.device_name()
            );
            assert!(bin.im.abs().to_f64().abs() <= 1.0e-28);
        }
        let restored = context
            .execute_double_double_stockham(&inverse, &spectrum)
            .unwrap();
        for (actual, expected) in restored.iter().zip(&input) {
            let re = (actual.re - expected.re).abs().to_f64().abs();
            let im = (actual.im - expected.im).abs().to_f64().abs();
            assert!(
                re <= 1.0e-28 && im <= 1.0e-28,
                "Vulkan DD round-trip mismatch on {}: actual={actual:?}, expected={expected:?}",
                context.device_name()
            );
        }

        let length = 15usize;
        let plan = FftPlan::build(
            FftConfig::new(vec![length]).with_precision(Precision::DoubleDoubleF64Storage),
        )
        .unwrap();
        let ir = crate::DoubleDoubleStockhamIr::build(&plan, Direction::Forward).unwrap();
        let input = (0..length)
            .map(|index| {
                let x = index as f64;
                Complex64::new((0.071 * x).sin() + x * 0.0002, (0.029 * x).cos())
            })
            .collect::<Vec<_>>();
        let expected = crate::execute_double_double_stockham_ir_f64_storage(&ir, &input).unwrap();
        let actual = context
            .execute_double_double_stockham_f64_storage(&ir, &input)
            .unwrap();
        let high_level = crate::TransformIr::build(
            FftConfig::new(vec![length]).with_precision(Precision::DoubleDoubleF64Storage),
            Direction::Forward,
            context.device_profile(),
        )
        .unwrap();
        let high_level_actual = context
            .execute_transform_double_double_f64_storage(&high_level, &input)
            .unwrap();
        assert_eq!(actual, high_level_actual);
        let max_error = actual
            .iter()
            .zip(&expected)
            .map(|(actual, expected)| (*actual - *expected).norm_sqr().sqrt())
            .fold(0.0, f64::max);
        assert!(
            max_error <= 3.0e-13 * length as f64,
            "Vulkan DD/F64-storage mismatch on {}: max_error={max_error:e}",
            context.device_name()
        );
    }

    #[test]
    fn gpu_double_double_grouped_quad_xy_matches_cpu_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        if !context.device_profile().supports_f64 {
            return;
        }
        for (length, expected_y) in [(16usize, 4usize), (15, 5), (72, 12)] {
            let ir = TransformIr::build(
                FftConfig::new(vec![length])
                    .with_batch_count(7)
                    .with_precision(Precision::DoubleDouble)
                    .with_grouped_batch(0, 3)
                    .unwrap(),
                Direction::Forward,
                context.device_profile(),
            )
            .unwrap();
            let TransformIr::Complex1dDoubleDouble(one_dim) = &ir else {
                panic!("grouped DD N={length} should build a 1D DD transform");
            };
            let crate::DoubleDoubleOneDimIr::Stockham(stockham) = one_dim else {
                panic!("grouped DD N={length} should remain Stockham");
            };
            let block = stockham.axis_batch_block.unwrap();
            assert_eq!(block.local_size_x, 3);
            assert_eq!(block.local_size_y, expected_y);
            let input = (0..length * 7)
                .map(|index| {
                    let x = index as f64;
                    crate::ComplexDoubleDouble::from_complex64(Complex64::new(
                        (0.071 * x).sin() + 0.0002 * x,
                        (0.029 * x).cos() - 0.0001 * x,
                    ))
                })
                .collect::<Vec<_>>();
            let expected = crate::execute_double_double_one_dim_ir(one_dim, &input).unwrap();
            let actual = context
                .execute_transform_double_double(&ir, &input)
                .unwrap();
            for (actual, expected) in actual.iter().zip(&expected) {
                assert!((actual.re - expected.re).abs().to_f64().abs() <= 1.0e-24);
                assert!((actual.im - expected.im).abs().to_f64().abs() <= 1.0e-24);
            }
        }
    }

    #[test]
    fn gpu_double_double_nd_higher_axis_n1922_three_upload_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let actual_device = context.device_profile();
        if !actual_device.supports_f64 {
            return;
        }
        let mut device = actual_device;
        device.shared_memory_bytes = 1024;
        device.shared_memory_pow2_bytes = 1024;
        device.max_threads_per_block = device.max_threads_per_block.min(32);
        let length = 2usize * 31 * 31;
        let dimensions = vec![length, 2usize];
        let forward = TransformIr::build(
            FftConfig::new(dimensions.clone()).with_precision(Precision::DoubleDouble),
            Direction::Forward,
            device,
        )
        .unwrap();
        let TransformIr::ComplexNdDoubleDouble(nd) = &forward else {
            panic!("Vulkan DD [1922,2] must use ND C2C IR");
        };
        let outer = nd.axes.iter().find(|axis| axis.axis == 0).unwrap();
        let crate::DoubleDoubleOneDimIr::Recursive(recursive) = &outer.transform else {
            panic!("Vulkan DD [1922,2] higher axis must use forced-Rader recursive IR");
        };
        let schedule = recursive
            .rader_forced_upload_schedule
            .as_ref()
            .expect("Vulkan DD [1922,2] forced-Rader schedule");
        assert_eq!(schedule.upload_count, 3);
        assert_eq!(schedule.axis_split.iter().product::<usize>(), length);
        if actual_device.vendor == crate::GpuVendor::Nvidia {
            assert_eq!(schedule.axis_split, vec![2, 31, 31]);
        }
        let components = recursive
            .forced_rader_three_upload_mapped_components()
            .unwrap()
            .expect("Vulkan DD [1922,2] should expose mapped three-upload components");
        assert!(components.iter().all(|component| match component {
            crate::double_double_recursive_ir::DoubleDoubleForcedRaderThreeUploadComponentIr::Stockham { ir, .. } =>
                ir.axis_batch_block.is_some_and(|block| block.transforms_on_x),
            crate::double_double_recursive_ir::DoubleDoubleForcedRaderThreeUploadComponentIr::Recursive { ir, .. } => match ir {
                crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::Stockham(ir) =>
                    ir.axis_batch_block.is_some_and(|block| block.transforms_on_x),
                crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::DirectRader(ir) =>
                    ir.axis_batch_block.is_some_and(|block| block.transforms_on_x),
                crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::FftRader(ir) =>
                    ir.caller_axis_batch_block.is_some_and(|block| block.transforms_on_x),
                crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::Bluestein(ir) =>
                    ir.wrapper_axis_batch_block().is_some_and(|block| block.transforms_on_x),
                crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::CooleyTukey(ir) =>
                    ir.pack_right.axis_batch_block.is_some_and(|block| block.transforms_on_x),
            },
        }));

        let mut input = vec![crate::ComplexDoubleDouble::default(); length * 2];
        input[2] = crate::ComplexDoubleDouble::new(
            crate::DoubleDouble::from_f64(1.0),
            crate::DoubleDouble::default(),
        );
        let actual = context
            .execute_transform_double_double(&forward, &input)
            .unwrap();
        let mut forward_error = 0.0f64;
        for k0 in 0..length {
            let expected = crate::double_double_unit_root(k0, length, Direction::Forward).unwrap();
            for k1 in 0..2 {
                let value = actual[k0 * 2 + k1];
                let re = (value.re - expected.re).abs();
                let im = (value.im - expected.im).abs();
                forward_error =
                    forward_error.max(re.hi.abs() + re.lo.abs() + im.hi.abs() + im.lo.abs());
            }
        }
        assert!(
            forward_error <= 5.0e-10,
            "Vulkan DD [1922,2] higher-axis three-upload mismatch on {}: {forward_error:e}",
            context.device_name()
        );

        let inverse = TransformIr::build(
            FftConfig::new(dimensions)
                .with_precision(Precision::DoubleDouble)
                .with_inverse_normalization(true),
            Direction::Inverse,
            device,
        )
        .unwrap();
        let restored = context
            .execute_transform_double_double(&inverse, &actual)
            .unwrap();
        let round_trip_error = restored
            .iter()
            .copied()
            .zip(input.iter().copied())
            .map(|(actual, expected)| {
                let re = (actual.re - expected.re).abs();
                let im = (actual.im - expected.im).abs();
                re.hi.abs() + re.lo.abs() + im.hi.abs() + im.lo.abs()
            })
            .fold(0.0, f64::max);
        assert!(
            round_trip_error <= 5.0e-12,
            "Vulkan DD [1922,2] higher-axis three-upload round trip mismatch on {}: {round_trip_error:e}",
            context.device_name()
        );
    }

    #[test]
    fn gpu_double_double_nd_higher_axis_p2053_recursive_bluestein_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let actual_device = context.device_profile();
        if !actual_device.supports_f64 || actual_device.shared_memory_bytes < 48 * 1024 {
            return;
        }
        let mut device = actual_device;
        device.shared_memory_bytes = 48 * 1024;
        device.shared_memory_pow2_bytes = 32 * 1024;
        let mut tuning = crate::PlannerTuning::for_device(device, Precision::DoubleDouble);
        tuning.max_rader_fft_prime = 100;
        let dimensions = vec![2_053usize, 2];
        let forward = TransformIr::build(
            FftConfig::new(dimensions.clone())
                .with_precision(Precision::DoubleDouble)
                .with_tuning(tuning),
            Direction::Forward,
            device,
        )
        .unwrap();
        let TransformIr::ComplexNdDoubleDouble(nd) = &forward else {
            panic!("Vulkan DD [2053,2] should build ND C2C IR");
        };
        let outer = nd.axes.iter().find(|axis| axis.axis == 0).unwrap();
        let crate::DoubleDoubleOneDimIr::Bluestein(bluestein) = &outer.transform else {
            panic!("Vulkan DD [2053,2] higher axis should use Bluestein");
        };
        assert_eq!(bluestein.convolution_len, 4_368);
        assert!(
            bluestein
                .wrapper_axis_batch_block()
                .is_some_and(|block| block.transforms_on_x)
        );
        let crate::DoubleDoubleBluesteinConvolutionIr::Recursive(child) = &bluestein.forward_fft
        else {
            panic!("Vulkan DD [2053,2] M4368 convolution should be recursive");
        };
        let crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::CooleyTukey(root) =
            &child.root
        else {
            panic!("Vulkan DD [2053,2] M4368 root should remain Cooley-Tukey");
        };
        assert!(
            root.pack_right
                .axis_batch_block
                .is_some_and(|block| block.transforms_on_x)
        );

        let input = (0..2_053 * 2)
            .map(|index| {
                let x = index as f64;
                crate::ComplexDoubleDouble::new(
                    crate::DoubleDouble::from_parts(
                        (0.013 * x).sin() + 0.00004 * x,
                        (index + 1) as f64 * 2.0e-31,
                    ),
                    crate::DoubleDouble::from_parts(
                        (0.023 * x).cos() - 0.00003 * x,
                        -(index as f64 + 1.0) * 1.0e-31,
                    ),
                )
            })
            .collect::<Vec<_>>();
        let expected = crate::execute_double_double_nd_ir(nd, &input).unwrap();
        let actual = context
            .execute_transform_double_double(&forward, &input)
            .unwrap();
        let dd_error = |actual: crate::ComplexDoubleDouble,
                        expected: crate::ComplexDoubleDouble| {
            let re = (actual.re - expected.re).abs();
            let im = (actual.im - expected.im).abs();
            re.hi.abs() + re.lo.abs() + im.hi.abs() + im.lo.abs()
        };
        let forward_error = actual
            .iter()
            .copied()
            .zip(expected.iter().copied())
            .map(|(actual, expected)| dd_error(actual, expected))
            .fold(0.0, f64::max);
        assert!(
            forward_error <= 5.0e-15,
            "Vulkan DD [2053,2] recursive Bluestein mismatch on {}: {forward_error:e}",
            context.device_name()
        );

        let inverse = TransformIr::build(
            FftConfig::new(dimensions)
                .with_precision(Precision::DoubleDouble)
                .with_inverse_normalization(true)
                .with_tuning(tuning),
            Direction::Inverse,
            device,
        )
        .unwrap();
        let restored = context
            .execute_transform_double_double(&inverse, &actual)
            .unwrap();
        let round_trip_error = restored
            .iter()
            .copied()
            .zip(input.iter().copied())
            .map(|(actual, expected)| dd_error(actual, expected))
            .fold(0.0, f64::max);
        assert!(
            round_trip_error <= 8.0e-14,
            "Vulkan DD [2053,2] recursive Bluestein round trip mismatch on {}: {round_trip_error:e}",
            context.device_name()
        );
    }

