    #[test]
    fn gpu_double_double_stockham_n1679616_two_upload_wide_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let actual_device = context.device_profile();
        if !actual_device.supports_f64
            || !matches!(
                actual_device.vendor,
                crate::GpuVendor::Nvidia | crate::GpuVendor::Amd
            )
        {
            return;
        }
        let planner_shared_bytes = match actual_device.vendor {
            crate::GpuVendor::Nvidia => 48 * 1024,
            crate::GpuVendor::Amd => 32 * 1024,
            _ => unreachable!("vendor gate accepts only NVIDIA or AMD"),
        };
        if actual_device.shared_memory_bytes < planner_shared_bytes {
            return;
        }
        let mut device = actual_device;
        device.shared_memory_bytes = planner_shared_bytes;
        device.shared_memory_pow2_bytes = 32 * 1024;
        let length = 1_679_616usize;
        let forward = crate::TransformIr::build(
            FftConfig::new(vec![length]).with_precision(Precision::DoubleDouble),
            Direction::Forward,
            device,
        )
        .unwrap();
        let crate::TransformIr::Complex1dDoubleDouble(crate::DoubleDoubleOneDimIr::Recursive(ir)) =
            &forward
        else {
            panic!("Vulkan DD N1679616 must use recursive upload scheduling");
        };
        let schedule = ir
            .stockham_upload_schedule
            .as_ref()
            .expect("Vulkan DD N1679616 must retain upload metadata");
        let expected_passes = match actual_device.vendor {
            crate::GpuVendor::Nvidia => {
                assert_eq!(schedule.axis_split, vec![1296, 1296]);
                let four_step = ir
                    .two_upload_four_step_plan
                    .as_ref()
                    .expect("NVIDIA DD N1679616 must retain two-upload Four-step metadata");
                assert!(ir.three_upload_four_step_plan.is_none());
                assert_eq!(
                    [
                        four_step.left_axis_block.grouped_batch,
                        four_step.left_axis_block.threads_per_transform,
                        four_step.left_axis_block.local_size_x,
                        four_step.left_axis_block.local_size_y,
                    ],
                    [1, 216, 216, 1]
                );
                assert!(!four_step.left_axis_block.transforms_on_x);
                assert!(!four_step.left_axis_block.axis_swapped);
                assert_eq!(
                    [
                        four_step.right_axis_block.grouped_batch,
                        four_step.right_axis_block.threads_per_transform,
                        four_step.right_axis_block.local_size_x,
                        four_step.right_axis_block.local_size_y,
                    ],
                    [1, 216, 1, 216]
                );
                assert!(four_step.right_axis_block.transforms_on_x);
                assert!(!four_step.right_axis_block.axis_swapped);
                2
            }
            crate::GpuVendor::Amd => {
                assert_eq!(schedule.axis_split, vec![144, 108, 108]);
                assert!(ir.two_upload_four_step_plan.is_none());
                let four_step = ir
                    .three_upload_four_step_plan
                    .as_ref()
                    .expect("AMD DD N1679616 must retain three-upload Four-step metadata");
                assert_eq!(four_step.axis_split, [144, 108, 108]);
                assert_eq!(
                    [
                        four_step.upload0_axis_block.grouped_batch,
                        four_step.upload0_axis_block.threads_per_transform,
                        four_step.upload0_axis_block.local_size_x,
                        four_step.upload0_axis_block.local_size_y,
                    ],
                    [4, 24, 4, 24]
                );
                assert!(four_step.upload0_axis_block.transforms_on_x);
                assert!(four_step.upload0_axis_block.axis_swapped);
                for block in [four_step.upload1_axis_block, four_step.upload2_axis_block] {
                    assert_eq!(
                        [
                            block.grouped_batch,
                            block.threads_per_transform,
                            block.local_size_x,
                            block.local_size_y,
                        ],
                        [8, 18, 8, 18]
                    );
                    assert!(block.transforms_on_x);
                    assert!(!block.axis_swapped);
                }
                3
            }
            _ => unreachable!("vendor gate accepts only NVIDIA or AMD"),
        };
        assert_eq!(
            crate::ProgramIr::double_double_recursive(ir)
                .unwrap()
                .passes
                .len(),
            expected_passes
        );

        let mut input = vec![crate::ComplexDoubleDouble::default(); length];
        input[1] = crate::ComplexDoubleDouble::new(
            crate::DoubleDouble::from_f64(1.0),
            crate::DoubleDouble::default(),
        );
        let actual = context
            .execute_transform_double_double(&forward, &input)
            .unwrap();
        let max_error = actual
            .iter()
            .enumerate()
            .map(|(index, actual)| {
                let angle = -std::f64::consts::TAU * index as f64 / length as f64;
                (actual.re.to_f64() - angle.cos()).hypot(actual.im.to_f64() - angle.sin())
            })
            .fold(0.0, f64::max);
        assert!(
            max_error <= 1.0e-9,
            "Vulkan DD N1679616 wide two-upload impulse mismatch on {}: {max_error:e}",
            context.device_name()
        );

        let inverse = crate::TransformIr::build(
            FftConfig::new(vec![length])
                .with_precision(Precision::DoubleDouble)
                .with_inverse_normalization(true),
            Direction::Inverse,
            device,
        )
        .unwrap();
        let restored = context
            .execute_transform_double_double(&inverse, &actual)
            .unwrap();
        let round_trip_error = restored
            .iter()
            .copied()
            .zip(input.iter().copied())
            .map(|(actual, expected)| {
                let re = (actual.re - expected.re).abs();
                let im = (actual.im - expected.im).abs();
                re.hi.abs() + re.lo.abs() + im.hi.abs() + im.lo.abs()
            })
            .fold(0.0, f64::max);
        assert!(
            round_trip_error <= 1.0e-11,
            "Vulkan DD N1679616 wide two-upload round trip mismatch on {}: {round_trip_error:e}",
            context.device_name()
        );

        let f64_forward = crate::TransformIr::build(
            FftConfig::new(vec![length]).with_precision(Precision::DoubleDoubleF64Storage),
            Direction::Forward,
            device,
        )
        .unwrap();
        let f64_input = input
            .iter()
            .copied()
            .map(crate::ComplexDoubleDouble::to_complex64)
            .collect::<Vec<_>>();
        let f64_actual = context
            .execute_transform_double_double_f64_storage(&f64_forward, &f64_input)
            .unwrap();
        let f64_error = f64_actual
            .iter()
            .enumerate()
            .map(|(index, actual)| {
                let angle = -std::f64::consts::TAU * index as f64 / length as f64;
                (actual.re - angle.cos()).hypot(actual.im - angle.sin())
            })
            .fold(0.0, f64::max);
        assert!(
            f64_error <= 1.0e-9,
            "Vulkan DD/F64 N1679616 wide two-upload mismatch on {}: {f64_error:e}",
            context.device_name()
        );
    }

