            || !matches!(
                actual_device.vendor,
                crate::GpuVendor::Nvidia | crate::GpuVendor::Amd
            )
            || actual_device.shared_memory_pow2_bytes < 32 * 1024
            || actual_device.max_threads_per_block < 128
