    #[test]
    fn gpu_grouped_higher_axis_two_upload_matches_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let mut planning_profile = context.device_profile();
        if planning_profile.shared_memory_bytes < 32 * 1024 {
            return;
        }
        planning_profile.shared_memory_bytes = 32 * 1024;
        planning_profile.shared_memory_pow2_bytes = 32 * 1024;
        let dimensions = vec![6_144usize, 8usize];
        let tensor_len = dimensions.iter().product::<usize>();
        let batch_count = 2usize;
        let mut input = vec![Complex32::new(0.0, 0.0); tensor_len * batch_count];
        for batch in 0..batch_count {
            let base = batch * tensor_len;
            input[base] = Complex32::new(1.0 + 0.125 * batch as f32, -0.0625);
            input[base + 1_234 * 8 + 3] = Complex32::new(-0.375, 0.1875 + 0.03125 * batch as f32);
        }
        let ir = crate::TransformIr::build(
            FftConfig::new(dimensions.clone())
                .with_batch_count(batch_count)
                .with_grouped_batch(0, 3)
                .unwrap()
                .with_grouped_batch(1, 3)
                .unwrap(),
            Direction::Forward,
            planning_profile,
        )
        .unwrap();
        let crate::TransformIr::ComplexNd(nd) = &ir else {
            panic!("Vulkan grouped N6144x8 probe did not build ComplexNd");
        };
        let outer = nd.axes.iter().find(|axis| axis.axis == 0).unwrap();
        let crate::OneDimFftIr::Recursive(recursive) = &outer.transform else {
            panic!("Vulkan grouped N6144 higher axis should be recursive");
        };
        assert_eq!(
            recursive
                .stockham_upload_schedule
                .as_ref()
                .unwrap()
                .axis_split,
            vec![96, 64]
        );
        assert!(
            recursive
                .four_step_plan
                .as_ref()
                .unwrap()
                .uploads
                .iter()
                .all(|upload| {
                    upload.axis_block.is_some_and(|block| {
                        block.grouped_batch == 3 && block.transforms_on_x && !block.axis_swapped
                    })
                })
        );

        let actual = match context
            .execute_transform_f32(&ir, TransformInput32::Complex(&input))
            .unwrap()
        {
            TransformOutput32::Complex(values) => values,
            TransformOutput32::Real(_) => panic!("grouped N6144x8 returned real output"),
        };
        let oracle_input = input
            .iter()
            .map(|value| Complex64::new(value.re as f64, value.im as f64))
            .collect::<Vec<_>>();
        let expected = ir.execute_complex_reference(&oracle_input).unwrap();
        let error = actual
            .iter()
            .zip(&expected)
            .map(|(actual, expected)| {
                let dr = actual.re as f64 - expected.re;
                let di = actual.im as f64 - expected.im;
                (dr * dr + di * di).sqrt()
            })
            .fold(0.0, f64::max);
        assert!(
            error <= 5.0e-3,
            "Vulkan grouped higher-axis two-upload error on {}: {error}",
            context.device_name()
        );
    }

    #[test]
    fn gpu_grouped_higher_axis_rader_matches_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        for prime in [34usize, 47, 94, 257] {
            let dimensions = vec![prime, 8usize];
            let tensor_len = dimensions.iter().product::<usize>();
            let batch_count = 2usize;
            let mut input = vec![Complex32::new(0.0, 0.0); tensor_len * batch_count];
            for batch in 0..batch_count {
                let base = batch * tensor_len;
                input[base] = Complex32::new(1.0 + 0.125 * batch as f32, -0.0625);
                input[base + (prime / 2) * 8 + 3] =
                    Complex32::new(-0.375, 0.1875 + 0.03125 * batch as f32);
            }
            for direction in [Direction::Forward, Direction::Inverse] {
                let ir = crate::TransformIr::build(
                    FftConfig::new(dimensions.clone())
                        .with_batch_count(batch_count)
                        .with_grouped_batch(0, 3)
                        .unwrap()
                        .with_grouped_batch(1, 3)
                        .unwrap()
                        .with_inverse_normalization(direction == Direction::Inverse),
                    direction,
                    context.device_profile(),
                )
                .unwrap();
                if prime == 94 && context.device_profile().vendor == GpuVendor::Nvidia {
                    let TransformIr::ComplexNd(nd) = &ir else {
                        panic!("Vulkan grouped N94x8 should build ComplexNd");
                    };
                    let outer = nd.axes.iter().find(|axis| axis.axis == 0).unwrap();
                    let crate::OneDimFftIr::Recursive(recursive) = &outer.transform else {
                        panic!("Vulkan grouped N94 higher axis should remain recursive");
                    };
                    let crate::recursive_ir::RecursiveFftNodeIr::CooleyTukey(root) =
                        &recursive.root
                    else {
                        panic!("Vulkan grouped N94 higher axis should keep a Cooley root");
                    };
                    let parent = root.pack_right.axis_batch_block.unwrap();
                    assert_eq!(parent.threads_per_transform, 48);
                    assert_eq!(parent.grouped_batch, 3);
                    assert_eq!([parent.local_size_x, parent.local_size_y], [3, 48]);
                    assert!(parent.transforms_on_x);
                    assert_eq!(root.twiddle_transpose.axis_batch_block, Some(parent));
                    assert_eq!(root.scatter_output.axis_batch_block, Some(parent));
                }
                let actual = match context
                    .execute_transform_f32(&ir, TransformInput32::Complex(&input))
                    .unwrap()
                {
                    TransformOutput32::Complex(values) => values,
                    TransformOutput32::Real(_) => {
                        panic!("grouped higher-axis Rader returned real output")
                    }
                };
                let oracle_input = input
                    .iter()
                    .map(|value| Complex64::new(value.re as f64, value.im as f64))
                    .collect::<Vec<_>>();
                let expected = ir.execute_complex_reference(&oracle_input).unwrap();
                let error = actual
                    .iter()
                    .zip(&expected)
                    .map(|(actual, expected)| {
                        let dr = actual.re as f64 - expected.re;
                        let di = actual.im as f64 - expected.im;
                        (dr * dr + di * di).sqrt()
                    })
                    .fold(0.0, f64::max);
                assert!(
                    error <= 3.0e-3,
                    "Vulkan grouped higher-axis p{prime} Rader error on {} {direction:?}: {error}",
                    context.device_name()
                );
            }
        }
    }

    #[test]
    fn gpu_grouped_higher_axis_bluestein_matches_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let mut tuning = crate::PlannerTuning::portable();
        tuning.max_rader_fft_prime = 100;
        let dimensions = vec![103usize, 8usize];
        let tensor_len = dimensions.iter().product::<usize>();
        let batch_count = 2usize;
        let mut input = vec![Complex32::new(0.0, 0.0); tensor_len * batch_count];
        for batch in 0..batch_count {
            let base = batch * tensor_len;
            input[base] = Complex32::new(1.0 + 0.125 * batch as f32, -0.0625);
            input[base + 51 * 8 + 3] = Complex32::new(-0.375, 0.1875 + 0.03125 * batch as f32);
        }
        for direction in [Direction::Forward, Direction::Inverse] {
            let ir = crate::TransformIr::build(
                FftConfig::new(dimensions.clone())
                    .with_batch_count(batch_count)
                    .with_grouped_batch(0, 3)
                    .unwrap()
                    .with_grouped_batch(1, 3)
                    .unwrap()
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_tuning(tuning),
                direction,
                context.device_profile(),
            )
            .unwrap();
            let crate::TransformIr::ComplexNd(nd) = &ir else {
                panic!("Vulkan grouped p103x8 Bluestein probe did not build ComplexNd");
            };
            let outer = nd.axes.iter().find(|axis| axis.axis == 0).unwrap();
            let crate::OneDimFftIr::Bluestein(pipeline) = &outer.transform else {
                panic!("Vulkan grouped p103 higher axis should remain Bluestein");
            };
            let block = pipeline.preprocess.axis_batch_block.unwrap();
            if context.device_profile().vendor == GpuVendor::Nvidia {
                assert_eq!([block.local_size_x, block.local_size_y], [3, 128]);
                assert!(block.transforms_on_x);
            } else {
                assert_eq!(block.grouped_batch, 3);
            }

            let actual = match context
                .execute_transform_f32(&ir, TransformInput32::Complex(&input))
                .unwrap()
            {
                TransformOutput32::Complex(values) => values,
                TransformOutput32::Real(_) => {
                    panic!("grouped higher-axis Bluestein returned real output")
                }
            };
            let oracle_input = input
                .iter()
                .map(|value| Complex64::new(value.re as f64, value.im as f64))
                .collect::<Vec<_>>();
            let expected = ir.execute_complex_reference(&oracle_input).unwrap();
            let error = actual
                .iter()
                .zip(&expected)
                .map(|(actual, expected)| {
                    let dr = actual.re as f64 - expected.re;
                    let di = actual.im as f64 - expected.im;
                    (dr * dr + di * di).sqrt()
                })
                .fold(0.0, f64::max);
            assert!(
                error <= 5.0e-3,
                "Vulkan grouped higher-axis Bluestein error on {} {direction:?}: {error}",
                context.device_name()
            );
        }
    }

    #[test]
    fn gpu_higher_axis_bluestein_nd_r2r_auto_group_matches_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let mut planning_profile = context.device_profile();
        if planning_profile.shared_memory_bytes < 48 * 1024
            || planning_profile.max_threads_per_block < 512
            || planning_profile.max_workgroup_size[0] < 4
            || planning_profile.max_workgroup_size[1] < 128
        {
            return;
        }
        planning_profile.shared_memory_bytes = 48 * 1024;
        planning_profile.shared_memory_pow2_bytes = 32 * 1024;
        let mut tuning = crate::PlannerTuning::portable();
        tuning.max_rader_fft_prime = 100;
        let dimensions = vec![103usize, 8usize];
        let tensor_len = dimensions.iter().product::<usize>();
        let input = (0..tensor_len)
            .map(|index| {
                let x = index as f32;
                (0.021 * x).sin() + 0.15 * (0.013 * x).cos() + 0.0002 * x
            })
            .collect::<Vec<_>>();

        for direction in [Direction::Forward, Direction::Inverse] {
            let ir = crate::TransformIr::build(
                FftConfig::new(dimensions.clone())
                    .with_transform(crate::TransformKind::Dct(crate::DctType::II))
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_tuning(tuning),
                direction,
                planning_profile,
            )
            .unwrap();
            let crate::TransformIr::RealToRealNd(nd) = &ir else {
                panic!("Vulkan p103x8 DCT-II probe did not build NdR2rIr");
            };
            let outer = nd.axes.iter().find(|axis| axis.axis == 0).unwrap();
            let reduction = outer.transform.fft_reduction.as_deref().unwrap();
            let crate::OneDimFftIr::Bluestein(pipeline) = &reduction.fft else {
                panic!("Vulkan p103 outer DCT-II reduction should use Bluestein");
            };
            let block = pipeline.preprocess.axis_batch_block.unwrap();
            assert!(block.grouped_batch > 1 && block.transforms_on_x);
            assert_eq!(block.threads_per_transform, 128);
            assert_eq!(pipeline.grouped_batch, 1);

            let actual = match context
                .execute_transform_f32(&ir, TransformInput32::Real(&input))
                .unwrap()
            {
                TransformOutput32::Real(values) => values,
                TransformOutput32::Complex(_) => panic!("Vulkan ND DCT-II returned complex output"),
            };
            let expected = ir
                .execute_r2r_reference(&input.iter().map(|value| *value as f64).collect::<Vec<_>>())
                .unwrap();
            let error = actual
                .iter()
                .zip(&expected)
                .map(|(actual, expected)| (*actual as f64 - expected).abs())
                .fold(0.0, f64::max);
            assert!(
                error <= 2.0e-3 * dimensions[0] as f64,
                "Vulkan auto-grouped higher-axis Bluestein ND DCT-II error on {} {direction:?}: {error}",
                context.device_name()
            );
        }
    }

    #[test]
    fn gpu_multidimensional_zero_padding_mixed_storage_matches_quantized_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let dimensions = vec![3usize, 4usize];
        let batch_count = 2usize;
        let length = dimensions.iter().product::<usize>() * batch_count;
        let input = (0..length)
            .map(|index| {
                let x = index as f32;
                Complex32::new((0.071 * x).sin() + x * 0.0005, (0.037 * x).cos())
            })
            .collect::<Vec<_>>();
        for precision in [
            Precision::F16StorageF32Compute,
            Precision::F64ComputeF32Storage,
        ] {
            if precision == Precision::F64ComputeF32Storage
                && !context.device_profile().supports_f64
            {
                continue;
            }
            for direction in [Direction::Forward, Direction::Inverse] {
                let config = FftConfig::new(dimensions.clone())
                    .with_batch_count(batch_count)
                    .with_precision(precision)
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_zero_padding(1, 2, 4)
                    .unwrap();
                let ir =
                    crate::TransformIr::build(config, direction, context.device_profile()).unwrap();
                let crate::TransformIr::ComplexNd(nd) = &ir else {
                    panic!("Vulkan ND zero-padded mixed-storage plan did not build ComplexNd");
                };
                assert!(nd.zero_pad_pass.is_some());
                let actual = match context
                    .execute_transform_f32(&ir, TransformInput32::Complex(&input))
                    .unwrap()
                {
                    TransformOutput32::Complex(values) => values,
                    TransformOutput32::Real(_) => panic!("ND C2C returned real output"),
                };
                let oracle_input = input
                    .iter()
                    .map(|value| {
                        if precision == Precision::F16StorageF32Compute {
                            Complex64::new(
                                crate::Binary16::from_f32(value.re).to_f32() as f64,
                                crate::Binary16::from_f32(value.im).to_f32() as f64,
                            )
                        } else {
                            Complex64::new(value.re as f64, value.im as f64)
                        }
                    })
                    .collect::<Vec<_>>();
                let mut expected = ir.execute_complex_reference(&oracle_input).unwrap();
                for value in &mut expected {
                    if precision == Precision::F16StorageF32Compute {
                        value.re = crate::Binary16::from_f32(value.re as f32).to_f32() as f64;
                        value.im = crate::Binary16::from_f32(value.im as f32).to_f32() as f64;
                    } else {
                        value.re = value.re as f32 as f64;
                        value.im = value.im as f32 as f64;
                    }
                }
                let error = actual
                    .iter()
                    .zip(&expected)
                    .map(|(actual, expected)| {
                        let dr = actual.re as f64 - expected.re;
                        let di = actual.im as f64 - expected.im;
                        (dr * dr + di * di).sqrt()
                    })
                    .fold(0.0, f64::max);
                let tolerance = if precision == Precision::F16StorageF32Compute {
                    1.2e-3 * dimensions.iter().product::<usize>() as f64
                } else {
                    4.0e-5 * dimensions.iter().product::<usize>() as f64
                };
                assert!(
                    error <= tolerance,
                    "Vulkan ND zero-padded mixed-storage error on {} {direction:?}: {error}",
                    context.device_name()
                );
            }
        }
    }

    #[test]
    fn gpu_zero_padding_mixed_storage_matches_quantized_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        for precision in [
            Precision::F16StorageF32Compute,
            Precision::F64ComputeF32Storage,
        ] {
            if precision == Precision::F64ComputeF32Storage
                && !context.device_profile().supports_f64
            {
                continue;
            }
            for (length, direction) in [
                (64usize, Direction::Forward),
                (64, Direction::Inverse),
                (49_152, Direction::Forward),
            ] {
                let left = length / 2;
                let config = FftConfig::new(vec![length])
                    .with_precision(precision)
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_zero_padding(0, left, length)
                    .unwrap();
                let ir =
                    crate::TransformIr::build(config, direction, context.device_profile()).unwrap();
                if length == 49_152 {
                    let crate::TransformIr::Complex1d(crate::OneDimFftIr::Recursive(recursive)) =
                        &ir
                    else {
                        panic!("Vulkan zero-padded multi-upload case did not remain recursive");
                    };
                    assert_eq!(
                        recursive
                            .stockham_upload_schedule
                            .as_ref()
                            .unwrap()
                            .upload_count,
                        2
                    );
                    assert!(recursive.four_step_plan.is_some());
                }
                let input = (0..length)
                    .map(|index| {
                        let x = index as f32;
                        Complex32::new(0.23 * (0.033 * x).sin(), 0.13 * (0.021 * x).cos())
                    })
                    .collect::<Vec<_>>();
                let actual = match context
                    .execute_transform_f32(&ir, TransformInput32::Complex(&input))
                    .unwrap()
                {
                    TransformOutput32::Complex(values) => values,
                    TransformOutput32::Real(_) => panic!("zero-padded C2C returned real output"),
                };
                let oracle_input = input
                    .iter()
                    .map(|value| {
                        if precision == Precision::F16StorageF32Compute {
                            Complex64::new(
                                crate::Binary16::from_f32(value.re).to_f32() as f64,
                                crate::Binary16::from_f32(value.im).to_f32() as f64,
                            )
                        } else {
                            Complex64::new(value.re as f64, value.im as f64)
                        }
                    })
                    .collect::<Vec<_>>();
                let mut expected = ir.execute_complex_reference(&oracle_input).unwrap();
                for value in &mut expected {
                    if precision == Precision::F16StorageF32Compute {
                        value.re = crate::Binary16::from_f32(value.re as f32).to_f32() as f64;
                        value.im = crate::Binary16::from_f32(value.im as f32).to_f32() as f64;
                    } else {
                        value.re = value.re as f32 as f64;
                        value.im = value.im as f32 as f64;
                    }
                }
                let error = actual
                    .iter()
                    .zip(&expected)
                    .map(|(actual, expected)| {
                        let dr = actual.re as f64 - expected.re;
                        let di = actual.im as f64 - expected.im;
                        (dr * dr + di * di).sqrt()
                    })
                    .fold(0.0, f64::max);
                let tolerance = if precision == Precision::F16StorageF32Compute {
                    1.0e-3 * length as f64
                } else {
                    3.0e-5 * length as f64
                };
                assert!(
                    error <= tolerance,
                    "Vulkan zero-pad mixed-storage error on {} N={length} {direction:?}: {error}",
                    context.device_name()
                );
                if direction == Direction::Inverse {
                    assert!(
                        actual[left..]
                            .iter()
                            .all(|value| value.re == 0.0 && value.im == 0.0)
                    );
                }
            }
        }
    }

