    #[test]
    fn gpu_recursive_mixed_storage_cooley_matches_quantized_reference_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let length = 256usize;
        let input = (0..length)
            .map(|index| {
                let x = index as f32;
                Complex32::new((0.047 * x).sin() + x * 0.00023, (0.019 * x).cos())
            })
            .collect::<Vec<_>>();
        for precision in [
            Precision::F16StorageF32Compute,
            Precision::F64ComputeF32Storage,
        ] {
            if precision == Precision::F64ComputeF32Storage
                && !context.device_profile().supports_f64
            {
                continue;
            }
            let mut profile = context.device_profile();
            profile.vendor = crate::GpuVendor::Other(0xD00D);
            profile.shared_memory_bytes = 64;
            profile.shared_memory_pow2_bytes = 64;
            let ir = crate::TransformIr::build(
                FftConfig::new(vec![length]).with_precision(precision),
                Direction::Forward,
                profile,
            )
            .unwrap();
            let crate::TransformIr::Complex1d(crate::OneDimFftIr::Recursive(recursive)) = &ir
            else {
                panic!("forced mixed-storage Vulkan plan did not build recursive C2C");
            };
            assert!(matches!(
                recursive.root,
                crate::RecursiveFftNodeIr::CooleyTukey(_)
            ));
            let actual = match context
                .execute_transform_f32(&ir, TransformInput32::Complex(&input))
                .unwrap()
            {
                TransformOutput32::Complex(values) => values,
                TransformOutput32::Real(_) => panic!("recursive mixed C2C returned real output"),
            };
            let oracle_input = input
                .iter()
                .map(|value| match precision {
                    Precision::F16StorageF32Compute => Complex64::new(
                        crate::Binary16::from_f32(value.re).to_f32() as f64,
                        crate::Binary16::from_f32(value.im).to_f32() as f64,
                    ),
                    Precision::F64ComputeF32Storage => {
                        Complex64::new(value.re as f64, value.im as f64)
                    }
                    _ => unreachable!(),
                })
                .collect::<Vec<_>>();
            let expected = ir
                .execute_complex_reference(&oracle_input)
                .unwrap()
                .into_iter()
                .map(|value| match precision {
                    Precision::F16StorageF32Compute => Complex32::new(
                        crate::Binary16::from_f32(value.re as f32).to_f32(),
                        crate::Binary16::from_f32(value.im as f32).to_f32(),
                    ),
                    Precision::F64ComputeF32Storage => {
                        Complex32::new(value.re as f32, value.im as f32)
                    }
                    _ => unreachable!(),
                })
                .collect::<Vec<_>>();
            let error = actual
                .iter()
                .zip(&expected)
                .map(|(actual, expected)| (*actual - *expected).norm_sqr().sqrt())
                .fold(0.0f32, f32::max);
            let tolerance = match precision {
                Precision::F16StorageF32Compute => 1.0e-3 * length as f32,
                Precision::F64ComputeF32Storage => 2.0e-5 * length as f32,
                _ => unreachable!(),
            };
            assert!(
                error <= tolerance,
                "Vulkan recursive {precision:?} error on {}: {error} > {tolerance}",
                context.device_name()
            );
        }
    }

    #[test]
    fn gpu_precision_sweep_tracks_upstream_four_error_metrics_or_skips_without_float64() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let profile = context.device_profile();
        if !profile.supports_f64 {
            return;
        }

        // Mirrors upstream sample_11_precision_VkFFT_single's four reported metrics:
        // avg/max absolute difference and avg/max per-bin relative epsilon. The same
        // deterministic F32 input values are promoted to F64 for the reference and
        // F64 VkFFT path, matching the upstream FFTW-double comparison methodology.
        for length in [64usize, 103, 257, 384] {
            let input32 = (0..length)
                .map(|index| {
                    let x = index as f32;
                    Complex32::new(
                        (0.137 * x).sin() + 0.0013 * x,
                        (0.071 * x).cos() - 0.0009 * x,
                    )
                })
                .collect::<Vec<_>>();
            let input64 = input32
                .iter()
                .map(|value| Complex64::new(value.re as f64, value.im as f64))
                .collect::<Vec<_>>();
            let reference = crate::reference::fft(&input64, Direction::Forward, false).unwrap();

            let mut tuning = crate::PlannerTuning::default();
            if length == 103 {
                tuning = crate::PlannerTuning::portable();
                tuning.max_rader_fft_prime = 100;
            }
            let plan32 = FftPlan::build(FftConfig::new(vec![length]).with_tuning(tuning)).unwrap();
            let ir32 = crate::OneDimFftIr::build(&plan32, Direction::Forward, profile).unwrap();
            let actual32 = context
                .execute_one_dim_fft_complex32(&ir32, &input32)
                .unwrap();
            let actual32_promoted = actual32
                .iter()
                .map(|value| Complex64::new(value.re as f64, value.im as f64))
                .collect::<Vec<_>>();
            let f32_metrics =
                crate::complex_precision_metrics(&actual32_promoted, &reference).unwrap();

            let plan64 = FftPlan::build(
                FftConfig::new(vec![length])
                    .with_precision(Precision::F64)
                    .with_tuning(tuning),
            )
            .unwrap();
            let ir64 = crate::OneDimFftIr::build(&plan64, Direction::Forward, profile).unwrap();
            let actual64 = context
                .execute_one_dim_fft_complex64(&ir64, &input64)
                .unwrap();
            let f64_metrics = crate::complex_precision_metrics(&actual64, &reference).unwrap();

            for value in [
                f32_metrics.avg_difference,
                f32_metrics.max_difference,
                f32_metrics.avg_eps,
                f32_metrics.max_eps,
                f64_metrics.avg_difference,
                f64_metrics.max_difference,
                f64_metrics.avg_eps,
                f64_metrics.max_eps,
            ] {
                assert!(
                    value.is_finite(),
                    "non-finite precision metric for N={length}"
                );
            }
            assert!(
                f32_metrics.max_difference <= 5.0e-3 * length as f64,
                "F32 max difference too large for N={length}: {f32_metrics:?}"
            );
            assert!(
                f32_metrics.avg_eps <= 5.0e-4,
                "F32 average relative epsilon too large for N={length}: {f32_metrics:?}"
            );
            assert!(
                f64_metrics.max_difference <= 1.0e-8 * length as f64,
                "F64 max difference too large for N={length}: {f64_metrics:?}"
            );
            assert!(
                f64_metrics.avg_eps <= 1.0e-9,
                "F64 average relative epsilon too large for N={length}: {f64_metrics:?}"
            );
            assert!(
                f64_metrics.avg_difference <= f32_metrics.avg_difference * 0.1,
                "F64 should materially improve average error for N={length}: f32={f32_metrics:?}, f64={f64_metrics:?}"
            );
        }
    }

    #[test]
    fn vulkan_precision_matrix_extends_to_nd_real_and_r2r_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        if !context.device_profile().supports_f64 {
            return;
        }

        let nd_shape = [17usize, 34usize];
        let tensor_len = nd_shape.iter().product::<usize>();
        let complex_input = (0..tensor_len)
            .map(|index| {
                let x = index as f32;
                Complex32::new(
                    (0.031 * x).sin() + 0.00021 * x,
                    (0.047 * x).cos() - 0.00013 * x,
                )
            })
            .collect::<Vec<_>>();
        let (f32_metrics, f64_metrics) =
            vulkan_complex_precision_case(&context, &nd_shape, &complex_input);
        assert_precision_case(
            &context,
            crate::PrecisionTransformFamily::C2cNd,
            &nd_shape,
            f32_metrics,
            f64_metrics,
        );

        let real_1d_shape = [65usize];
        let real_1d = (0..real_1d_shape[0])
            .map(|index| {
                let x = index as f32;
                (0.083 * x).sin() + 0.23 * (0.029 * x).cos() + 0.0007 * x
            })
            .collect::<Vec<_>>();
        let (f32_metrics, f64_metrics) =
            vulkan_r2c_precision_case(&context, &real_1d_shape, &real_1d);
        assert_precision_case(
            &context,
            crate::PrecisionTransformFamily::R2c1d,
            &real_1d_shape,
            f32_metrics,
            f64_metrics,
        );

        let real_nd = (0..tensor_len)
            .map(|index| {
                let x = index as f32;
                (0.057 * x).sin() + 0.19 * (0.017 * x).cos() - 0.00031 * x
            })
            .collect::<Vec<_>>();
        let (f32_metrics, f64_metrics) = vulkan_r2c_precision_case(&context, &nd_shape, &real_nd);
        assert_precision_case(
            &context,
            crate::PrecisionTransformFamily::R2cNd,
            &nd_shape,
            f32_metrics,
            f64_metrics,
        );

        let r2r_1d_shape = [257usize];
        let r2r_1d = (0..r2r_1d_shape[0])
            .map(|index| {
                let x = index as f32;
                (0.041 * x).sin() + 0.13 * (0.023 * x).cos() + 0.00011 * x
            })
            .collect::<Vec<_>>();
        let (f32_metrics, f64_metrics) =
            vulkan_r2r_precision_case(&context, &r2r_1d_shape, &r2r_1d);
        assert_precision_case(
            &context,
            crate::PrecisionTransformFamily::R2r1d,
            &r2r_1d_shape,
            f32_metrics,
            f64_metrics,
        );

        let r2r_nd = (0..tensor_len)
            .map(|index| {
                let x = index as f32;
                (0.037 * x).sin() + 0.17 * (0.019 * x).cos() + 0.00009 * x
            })
            .collect::<Vec<_>>();
        let (f32_metrics, f64_metrics) = vulkan_r2r_precision_case(&context, &nd_shape, &r2r_nd);
        assert_precision_case(
            &context,
            crate::PrecisionTransformFamily::R2rNd,
            &nd_shape,
            f32_metrics,
            f64_metrics,
        );
    }

