    #[test]
    fn repeated_context_creation_keeps_driver_loaded_or_skip() {
        if std::env::var_os("VKFFT_RUN_VULKAN_CONTEXT_STRESS").is_none() {
            return;
        }
        let first = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("initial Vulkan context bootstrap failed: {error}"),
        };
        let device_name = first.device_name();
        drop(first);

        for iteration in 0..128usize {
            let context = VulkanExecutionContext::new().unwrap_or_else(|error| {
                panic!(
                    "Vulkan context recreation failed after successful bootstrap at iteration {iteration}: {error}"
                )
            });
            assert_eq!(context.device_name(), device_name);
        }
    }

    #[test]
    fn pipeline_cache_round_trips_when_vulkan_available() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let identity = context.pipeline_cache_identity();
        let length = 32usize;
        let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
        let ir =
            KernelIr::stockham_1d(&plan, Direction::Forward, context.device_profile()).unwrap();
        let shader = VulkanGlslBackend
            .lower(&ir)
            .unwrap()
            .compile_spirv()
            .unwrap();
        let input = (0..length)
            .map(|index| Complex32::new(index as f32 * 0.25, -(index as f32) * 0.125))
            .collect::<Vec<_>>();
        let expected = context.execute_complex32(&shader, &input).unwrap();
        let cache_archive = context.pipeline_cache_archive_data().unwrap();
        let decoded = VulkanPipelineCacheArchive::decode(&cache_archive).unwrap();
        assert_eq!(decoded.identity, identity);
        assert!(!decoded.data.is_empty());

        let mut wrong_identity = decoded.clone();
        wrong_identity.identity.device_id ^= 1;
        let wrong_archive = wrong_identity.encode();
        assert!(matches!(
            VulkanExecutionContext::new_with_pipeline_cache_archive(&wrong_archive),
            Err(VkFftError::VulkanRuntime(_))
        ));
        drop(context);

        let restored =
            VulkanExecutionContext::new_with_pipeline_cache_archive(&cache_archive).unwrap();
        assert_eq!(restored.pipeline_cache_identity(), identity);
        let actual = restored.execute_complex32(&shader, &input).unwrap();
        assert_eq!(actual.len(), expected.len());
        for (actual, expected) in actual.iter().zip(expected) {
            assert!((actual.re - expected.re).abs() <= 1.0e-5);
            assert!((actual.im - expected.im).abs() <= 1.0e-5);
        }
        assert!(!restored.pipeline_cache_archive_data().unwrap().is_empty());
    }

    #[test]
    fn explicit_device_pipeline_cache_round_trips_when_vulkan_available() {
        let context = match VulkanExecutionContext::new_with_device_index(0) {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan device-index bootstrap failed: {error}"),
        };
        let identity = context.pipeline_cache_identity();
        let device_name = context.device_name().to_owned();
        let length = 32usize;
        let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
        let ir =
            KernelIr::stockham_1d(&plan, Direction::Forward, context.device_profile()).unwrap();
        let shader = VulkanGlslBackend
            .lower(&ir)
            .unwrap()
            .compile_spirv()
            .unwrap();
        let input = (0..length)
            .map(|index| Complex32::new(index as f32 * 0.125, -(index as f32) * 0.375))
            .collect::<Vec<_>>();
        let expected = context.execute_complex32(&shader, &input).unwrap();
        let cache_archive = context.pipeline_cache_archive_data().unwrap();
        let decoded = VulkanPipelineCacheArchive::decode(&cache_archive).unwrap();
        assert_eq!(decoded.identity, identity);
        assert!(!decoded.data.is_empty());
        drop(context);

        let restored_raw =
            VulkanExecutionContext::new_with_device_index_and_pipeline_cache_data(0, &decoded.data)
                .unwrap();
        assert_eq!(restored_raw.device_name(), device_name);
        assert_eq!(restored_raw.pipeline_cache_identity(), identity);
        let actual = restored_raw.execute_complex32(&shader, &input).unwrap();
        assert_eq!(actual.len(), expected.len());
        for (actual, expected) in actual.iter().zip(&expected) {
            assert!((actual.re - expected.re).abs() <= 1.0e-5);
            assert!((actual.im - expected.im).abs() <= 1.0e-5);
        }
        drop(restored_raw);

        let restored_archive =
            VulkanExecutionContext::new_with_device_index_and_pipeline_cache_archive(
                0,
                &cache_archive,
            )
            .unwrap();
        assert_eq!(restored_archive.device_name(), device_name);
        assert_eq!(restored_archive.pipeline_cache_identity(), identity);
        let actual = restored_archive.execute_complex32(&shader, &input).unwrap();
        assert_eq!(actual.len(), expected.len());
        for (actual, expected) in actual.iter().zip(&expected) {
            assert!((actual.re - expected.re).abs() <= 1.0e-5);
            assert!((actual.im - expected.im).abs() <= 1.0e-5);
        }
        drop(restored_archive);

        let mut wrong_identity = decoded;
        wrong_identity.identity.device_id ^= 1;
        assert!(matches!(
            VulkanExecutionContext::new_with_device_index_and_pipeline_cache_archive(
                0,
                &wrong_identity.encode(),
            ),
            Err(VkFftError::VulkanRuntime(_))
        ));
        assert!(matches!(
            VulkanExecutionContext::new_with_device_index_and_pipeline_cache_archive(
                usize::MAX,
                &cache_archive,
            ),
            Err(VkFftError::VulkanUnavailable(_))
        ));
    }

    #[test]
    fn runtime_object_pools_reuse_when_vulkan_available() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        assert_eq!(context.cached_staging_buffer_count().unwrap(), 0);
        assert_eq!(context.cached_pipeline_object_count().unwrap(), 0);
        assert_eq!(context.cached_transient_buffer_count().unwrap(), 0);
        assert_eq!(context.cached_submission_slot_count().unwrap(), 0);

        let length = 32usize;
        let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
        let ir =
            KernelIr::stockham_1d(&plan, Direction::Forward, context.device_profile()).unwrap();
        let shader = VulkanGlslBackend
            .lower(&ir)
            .unwrap()
            .compile_spirv()
            .unwrap();
        let input = (0..length)
            .map(|index| Complex32::new(index as f32 * 0.125, -(index as f32) * 0.03125))
            .collect::<Vec<_>>();

        let first = context.execute_complex32(&shader, &input).unwrap();
        let staging_after_first = context.cached_staging_buffer_count().unwrap();
        let transient_after_first = context.cached_transient_buffer_count().unwrap();
        assert_eq!(context.cached_pipeline_object_count().unwrap(), 1);
        assert_eq!(staging_after_first, 2);
        assert_eq!(transient_after_first, 2);
        assert_eq!(context.cached_submission_slot_count().unwrap(), 1);

        let second = context.execute_complex32(&shader, &input).unwrap();
        assert_eq!(
            context.cached_staging_buffer_count().unwrap(),
            staging_after_first
        );
        assert_eq!(
            context.cached_transient_buffer_count().unwrap(),
            transient_after_first
        );
        assert_eq!(context.cached_pipeline_object_count().unwrap(), 1);
        assert_eq!(context.cached_submission_slot_count().unwrap(), 1);
        assert_eq!(first, second);

        context.clear_cached_runtime_objects().unwrap();
        assert_eq!(context.cached_staging_buffer_count().unwrap(), 0);
        assert_eq!(context.cached_pipeline_object_count().unwrap(), 0);
        assert_eq!(context.cached_submission_slot_count().unwrap(), 0);
        context.clear_cached_transient_buffers().unwrap();
        assert_eq!(context.cached_transient_buffer_count().unwrap(), 0);
    }

    #[test]
    fn gpu_device_resident_program_chain_round_trips_and_rejects_mismatch_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let profile = context.device_profile();
        let batch_count = 3usize;
        let build = |length: usize, direction: Direction| {
            let plan = FftPlan::build(
                FftConfig::new(vec![length])
                    .with_batch_count(batch_count)
                    .with_inverse_normalization(direction == Direction::Inverse),
            )
            .unwrap();
            let ir = crate::OneDimFftIr::build(&plan, direction, profile).unwrap();
            let shaders = VulkanGlslBackend
                .lower_one_dim_fft(&ir)
                .unwrap()
                .into_iter()
                .map(|shader| shader.compile_spirv())
                .collect::<Result<Vec<_>>>()
                .unwrap();
            let program = ProgramIr::one_dim_fft(&ir).unwrap();
            (program, shaders)
        };
        let (forward_program, forward_shaders) = build(64, Direction::Forward);
        let (inverse_program, inverse_shaders) = build(64, Direction::Inverse);
        let (mismatch_program, mismatch_shaders) = build(32, Direction::Inverse);
        let input = (0..64 * batch_count)
            .map(|index| {
                let x = index as f32;
                Complex32::new(
                    (0.071 * x).sin() + x * 0.0007,
                    (0.043 * x).cos() - x * 0.0003,
                )
            })
            .collect::<Vec<_>>();

        let host_forward = context
            .execute_program_complex32(&forward_program, &forward_shaders, &input)
            .unwrap();
        let host_round_trip = context
            .execute_program_complex32(&inverse_program, &inverse_shaders, &host_forward)
            .unwrap();
        let resident_round_trip = context
            .execute_program_chain_complex32(
                &[
                    (&forward_program, &forward_shaders),
                    (&inverse_program, &inverse_shaders),
                ],
                &input,
            )
            .unwrap();
        let resident_forward = context
            .execute_program_chain_complex32(&[(&forward_program, &forward_shaders)], &input)
            .unwrap();
        let chain = [
            (&forward_program, forward_shaders.as_slice()),
            (&inverse_program, inverse_shaders.as_slice()),
        ];
        let mut direct_output = vec![Complex32::new(123.0, -456.0); input.len()];
        let direct_output_ptr = direct_output.as_ptr();
        for _ in 0..2 {
            context
                .execute_program_chain_complex32_into(&chain, &input, &mut direct_output)
                .unwrap();
            assert_eq!(direct_output.as_ptr(), direct_output_ptr);
            for (direct, resident) in direct_output.iter().zip(&resident_round_trip) {
                assert!((direct.re - resident.re).abs() <= 1.0e-6);
                assert!((direct.im - resident.im).abs() <= 1.0e-6);
            }
            direct_output.fill(Complex32::new(-9.0, 7.0));
        }

        assert_eq!(resident_forward.len(), host_forward.len());
        for (resident, host) in resident_forward.iter().zip(&host_forward) {
            assert!((resident.re - host.re).abs() <= 1.0e-6);
            assert!((resident.im - host.im).abs() <= 1.0e-6);
        }
        assert_eq!(resident_round_trip.len(), host_round_trip.len());
        for ((resident, host), expected) in
            resident_round_trip.iter().zip(&host_round_trip).zip(&input)
        {
            assert!((resident.re - host.re).abs() <= 1.0e-6);
            assert!((resident.im - host.im).abs() <= 1.0e-6);
            assert!((resident.re - expected.re).abs() <= 2.5e-4);
            assert!((resident.im - expected.im).abs() <= 2.5e-4);
        }
        let mut short_output = vec![Complex32::default(); input.len() - 1];
        assert!(matches!(
            context.execute_program_chain_complex32_into(&chain, &input, &mut short_output),
            Err(VkFftError::InvalidKernelIr(_))
        ));

        let f16_plan = FftPlan::build(
            FftConfig::new(vec![64])
                .with_batch_count(batch_count)
                .with_precision(Precision::F16StorageF32Compute),
        )
        .unwrap();
        let f16_ir = crate::OneDimFftIr::build(&f16_plan, Direction::Forward, profile).unwrap();
        let f16_shaders = VulkanGlslBackend
            .lower_one_dim_fft(&f16_ir)
            .unwrap()
            .into_iter()
            .map(|shader| shader.compile_spirv())
            .collect::<Result<Vec<_>>>()
            .unwrap();
        let f16_program = ProgramIr::one_dim_fft(&f16_ir).unwrap();
        assert!(matches!(
            context.execute_program_chain_complex32_into(
                &[(&f16_program, f16_shaders.as_slice())],
                &input,
                &mut direct_output,
            ),
            Err(VkFftError::InvalidKernelIr(_))
        ));

        assert!(matches!(
            context.execute_program_chain_complex32(
                &[
                    (&forward_program, &forward_shaders),
                    (&mismatch_program, &mismatch_shaders),
                ],
                &input,
            ),
            Err(VkFftError::InvalidKernelIr(_))
        ));
        assert!(matches!(
            context.execute_program_chain_complex32(&[], &input),
            Err(VkFftError::InvalidKernelIr(_))
        ));
    }

    #[test]
    fn gpu_async_multi_in_flight_programs_match_cpu_or_skip_without_vulkan() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let profile = context.device_profile();
        let make_case = |length: usize| {
            let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
            let ir = crate::OneDimFftIr::build(&plan, Direction::Forward, profile).unwrap();
            let input = (0..length)
                .map(|index| {
                    let x = index as f32;
                    Complex32::new(
                        (0.071 * x).sin() + x * 0.0007,
                        (0.043 * x).cos() - x * 0.0003,
                    )
                })
                .collect::<Vec<_>>();
            (ir, input)
        };
        let (stockham_ir, stockham_input) = make_case(64);
        let (bluestein_ir, bluestein_input) = make_case(103);
        assert_eq!(context.cached_submission_slot_count().unwrap(), 0);
        assert_eq!(context.cached_async_pipeline_object_count().unwrap(), 0);

        let stockham_ticket = context
            .submit_one_dim_fft_complex32_async(&stockham_ir, &stockham_input)
            .unwrap();
        let bluestein_ticket = context
            .submit_one_dim_fft_complex32_async(&bluestein_ir, &bluestein_input)
            .unwrap();
        // Both submissions are live: neither command-buffer/fence slot nor mutable
        // descriptor instance is eligible for reuse before its ticket completes.
        assert_eq!(context.cached_submission_slot_count().unwrap(), 0);
        assert_eq!(context.cached_async_pipeline_object_count().unwrap(), 0);

        let bluestein_actual = bluestein_ticket.wait().unwrap();
        assert_eq!(context.cached_submission_slot_count().unwrap(), 1);
        let stockham_actual = stockham_ticket.wait().unwrap();
        assert_eq!(context.cached_submission_slot_count().unwrap(), 2);
        assert!(context.cached_async_pipeline_object_count().unwrap() >= 2);

        for (length, input, actual) in [
            (64usize, &stockham_input[..], &stockham_actual[..]),
            (103usize, &bluestein_input[..], &bluestein_actual[..]),
        ] {
            let oracle_input = input
                .iter()
                .map(|value| Complex64::new(value.re as f64, value.im as f64))
                .collect::<Vec<_>>();
            let expected = crate::reference::fft(&oracle_input, Direction::Forward, false).unwrap();
            let tolerance = 2.5e-3 * length as f64;
            for (actual, expected) in actual.iter().zip(expected) {
                assert!(
                    (actual.re as f64 - expected.re).abs() <= tolerance
                        && (actual.im as f64 - expected.im).abs() <= tolerance,
                    "async Vulkan mismatch on {} for N={length}: actual={actual:?}, expected={expected:?}",
                    context.device_name()
                );
            }
        }
    }

    #[test]
    fn repeated_program_shaders_use_distinct_cached_descriptor_slots_when_vulkan_available() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let length = 17usize * 17;
        let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
        let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, context.device_profile())
            .unwrap();
        let shaders = VulkanGlslBackend
            .lower_recursive_fft(&ir)
            .unwrap()
            .into_iter()
            .map(|shader| shader.compile_spirv())
            .collect::<Result<Vec<_>>>()
            .unwrap();
        let program = ProgramIr::recursive_fft(&ir).unwrap();
        let keys = shaders
            .iter()
            .map(VulkanExecutionContext::pipeline_object_key)
            .collect::<Vec<_>>();
        assert!(
            keys.iter()
                .enumerate()
                .any(|(index, key)| keys[..index].contains(key)),
            "fixture must contain at least one repeated Vulkan shader key"
        );
        let input = (0..length)
            .map(|index| {
                let x = index as f32;
                Complex32::new((0.031 * x).sin(), (0.017 * x).cos())
            })
            .collect::<Vec<_>>();

        let first = context
            .execute_program_complex32(&program, &shaders, &input)
            .unwrap();
        assert_eq!(first.len(), length);
        let cached_after_first = context.cached_pipeline_object_count().unwrap();
        assert_eq!(cached_after_first, shaders.len());

        let second = context
            .execute_program_complex32(&program, &shaders, &input)
            .unwrap();
        assert_eq!(first, second);
        assert_eq!(
            context.cached_pipeline_object_count().unwrap(),
            cached_after_first
        );
    }

    #[test]
    fn persistent_lut_cache_reuses_and_clears_when_vulkan_available() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        assert_eq!(context.cached_lut_count().unwrap(), 0);
        assert_eq!(context.cached_transient_buffer_count().unwrap(), 0);

        let length = 103usize;
        let batch_count = 2usize;
        let mut bluestein_tuning = crate::PlannerTuning::portable();
        bluestein_tuning.max_rader_fft_prime = 100;
        let plan = FftPlan::build(
            FftConfig::new(vec![length])
                .with_batch_count(batch_count)
                .with_tuning(bluestein_tuning),
        )
        .unwrap();
        let pipeline =
            crate::BluesteinPipelineIr::build(&plan, Direction::Forward, context.device_profile())
                .unwrap();
        let input = (0..length * batch_count)
            .map(|index| {
                let x = index as f32;
                Complex32::new((0.11 * x).sin() + x * 0.001, (0.07 * x).cos() - x * 0.002)
            })
            .collect::<Vec<_>>();

        let first = context
            .execute_bluestein_complex32(&pipeline, &input)
            .unwrap();
        let cached_after_first = context.cached_lut_count().unwrap();
        assert!(cached_after_first >= 1);
        let transients_after_first = context.cached_transient_buffer_count().unwrap();
        assert!(transients_after_first >= 1);

        // Allocate the same logical program again without executing it. Every LUT
        // allocation must resolve to the resident device-local cache and therefore
        // require no staging upload on this second construction.
        let program = ProgramIr::bluestein(&pipeline).unwrap();
        let memory_plan = program.memory_plan().unwrap();
        let storage = context
            .allocate_program_storage(&program, &memory_plan)
            .unwrap();
        let mut saw_lut = false;
        for (index, allocation) in memory_plan.allocations.iter().enumerate() {
            if allocation.kind == ProgramAllocationKind::LookupTable {
                saw_lut = true;
                assert!(!storage.upload_required[index]);
            }
        }
        assert!(saw_lut);
        assert!(context.cached_transient_buffer_count().unwrap() < transients_after_first);
        context
            .recycle_program_transients(&memory_plan, &storage.device_local)
            .unwrap();
        drop(storage);
        assert_eq!(
            context.cached_transient_buffer_count().unwrap(),
            transients_after_first
        );

        let second = context
            .execute_bluestein_complex32(&pipeline, &input)
            .unwrap();
        assert_eq!(context.cached_lut_count().unwrap(), cached_after_first);
        assert_eq!(
            context.cached_transient_buffer_count().unwrap(),
            transients_after_first
        );
        for (actual, expected) in second.iter().zip(first) {
            assert!((actual.re - expected.re).abs() <= 1.0e-5);
            assert!((actual.im - expected.im).abs() <= 1.0e-5);
        }

        context.clear_cached_luts().unwrap();
        assert_eq!(context.cached_lut_count().unwrap(), 0);
        context.clear_cached_transient_buffers().unwrap();
        assert_eq!(context.cached_transient_buffer_count().unwrap(), 0);
    }

    #[test]
    fn fft_rader_auxiliary_shader_satisfies_runtime_contract() {
        let plan = FftPlan::build(FftConfig::new(vec![17]).with_batch_count(2)).unwrap();
        let mut profile = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        profile.shared_memory_bytes = 128 * 1024;
        let pipeline =
            crate::RaderFftPipelineIr::build(&plan, Direction::Forward, profile).unwrap();
        let shader = VulkanGlslBackend
            .lower_rader_fft_pass(&pipeline, &pipeline.scatter)
            .unwrap()
            .compile_spirv()
            .unwrap();
        validate_runtime_contract(&shader).unwrap();
        assert_eq!(shader.descriptors[2].role, BufferRole::Auxiliary);
    }

    #[test]
    fn gpu_nested_direct_sub_rader_composite_n566_parent_floor_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let profile = context.device_profile();
        let length = 2usize * 283;
        let batch_count = 2usize;
        let Some(expected_threads) =
            crate::scheduler::plan_gpu_axis0_multi_fft_rader_threads_for_prime_multiplicities(
                length,
                &[(283, 1)],
                batch_count,
                profile,
            )
            .unwrap()
        else {
            return;
        };
        let tuning = crate::PlannerTuning::portable().with_recursive_fft_rader(true);
        let build = |direction| {
            TransformIr::build(
                FftConfig::new(vec![length])
                    .with_batch_count(batch_count)
                    .with_tuning(tuning)
                    .with_inverse_normalization(direction == Direction::Inverse),
                direction,
                profile,
            )
            .unwrap()
        };
        let forward = build(Direction::Forward);
        let inverse = build(Direction::Inverse);
        for transform in [&forward, &inverse] {
            let TransformIr::Complex1d(crate::OneDimFftIr::Recursive(ir)) = transform else {
                panic!("Vulkan N566 nested direct sub-Rader should remain recursive C2C");
            };
            let crate::recursive_ir::RecursiveFftNodeIr::CooleyTukey(root) = &ir.root else {
                panic!("Vulkan N566 should keep smooth-2 x p283 Cooley root");
            };
            let block = root.pack_right.axis_batch_block.unwrap();
            assert_eq!(block.threads_per_transform, expected_threads);
            assert_eq!(
                [block.local_size_x, block.local_size_y],
                [expected_threads, 1]
            );
            let outer = match (&root.left, &root.right) {
                (crate::recursive_ir::RecursiveFftNodeIr::FftRader(rader), _)
                    if rader.prime == 283 =>
                {
                    rader
                }
                (_, crate::recursive_ir::RecursiveFftNodeIr::FftRader(rader))
                    if rader.prime == 283 =>
                {
                    rader
                }
                _ => panic!("Vulkan N566 should contain p283 FFT-Rader child"),
            };
            fn contains_direct_prime(
                node: &crate::recursive_ir::RecursiveFftNodeIr,
                prime: usize,
            ) -> bool {
                match node {
                    crate::recursive_ir::RecursiveFftNodeIr::DirectRader(direct) => {
                        direct.prime == prime
                    }
                    crate::recursive_ir::RecursiveFftNodeIr::CooleyTukey(cooley) => {
                        contains_direct_prime(&cooley.left, prime)
                            || contains_direct_prime(&cooley.right, prime)
                    }
                    _ => false,
                }
            }
            assert!(contains_direct_prime(
                &outer.forward_recursive().unwrap().root,
                47
            ));
        }
        let mut input = vec![Complex32::new(0.0, 0.0); length * batch_count];
        for batch in 0..batch_count {
            input[batch * length + 1] = Complex32::new(1.0, 0.0);
        }
        let spectrum = match context
            .execute_transform_f32(&forward, TransformInput32::Complex(&input))
            .unwrap()
        {
            TransformOutput32::Complex(values) => values,
            TransformOutput32::Real(_) => panic!("Vulkan N566 C2C returned real output"),
        };
        let forward_error = spectrum
            .iter()
            .enumerate()
            .map(|(index, actual)| {
                let k = index % length;
                let angle = -std::f32::consts::TAU * k as f32 / length as f32;
                (actual.re - angle.cos()).hypot(actual.im - angle.sin())
            })
            .fold(0.0f32, f32::max);
        assert!(forward_error <= 4.0e-3);
        let restored = match context
            .execute_transform_f32(&inverse, TransformInput32::Complex(&spectrum))
            .unwrap()
        {
            TransformOutput32::Complex(values) => values,
            TransformOutput32::Real(_) => panic!("Vulkan inverse N566 C2C returned real output"),
        };
        let round_trip_error = restored
            .iter()
            .zip(&input)
            .map(|(actual, expected)| (*actual - *expected).norm_sqr().sqrt())
            .fold(0.0f32, f32::max);
        assert!(round_trip_error <= 4.0e-3);
    }

    #[test]
    fn gpu_nested_device_capped_sub_rader_n566_or_skip() {
        let context = match VulkanExecutionContext::new() {
            Ok(context) => context,
            Err(VkFftError::VulkanUnavailable(_)) => return,
            Err(error) => panic!("Vulkan bootstrap failed after loader/device discovery: {error}"),
        };
        let mut profile = context.device_profile();
        profile.max_threads_per_block = profile.max_threads_per_block.min(64);
        profile.max_workgroup_size[0] = profile.max_workgroup_size[0].min(64);
        let length = 2usize * 283;
        let batch_count = 2usize;
        let tuning = crate::PlannerTuning::portable().with_recursive_fft_rader(true);
        let effective =
            crate::config::upstream_effective_rader_tuning(tuning, profile, crate::Precision::F32);
        if effective.max_rader_direct_prime != 31 {
            return;
        }
        let build = |direction| {
            TransformIr::build(
                FftConfig::new(vec![length])
                    .with_batch_count(batch_count)
                    .with_tuning(tuning)
                    .with_inverse_normalization(direction == Direction::Inverse),
                direction,
                profile,
            )
            .unwrap()
        };
        let forward = build(Direction::Forward);
        let inverse = build(Direction::Inverse);
        for transform in [&forward, &inverse] {
            let TransformIr::Complex1d(crate::OneDimFftIr::Recursive(ir)) = transform else {
                panic!("Vulkan device-capped N566 should remain recursive C2C");
            };
            let crate::recursive_ir::RecursiveFftNodeIr::CooleyTukey(root) = &ir.root else {
                panic!("Vulkan device-capped N566 should keep smooth-2 x p283 Cooley root");
            };
            let block = root.pack_right.axis_batch_block.unwrap();
            assert_eq!(block.threads_per_transform, 19);
            assert_eq!([block.local_size_x, block.local_size_y], [19, 1]);
            let outer = match (&root.left, &root.right) {
                (crate::recursive_ir::RecursiveFftNodeIr::FftRader(rader), _)
                    if rader.prime == 283 =>
                {
                    rader
                }
                (_, crate::recursive_ir::RecursiveFftNodeIr::FftRader(rader))
                    if rader.prime == 283 =>
                {
                    rader
                }
                _ => panic!("Vulkan device-capped N566 should contain p283 FFT-Rader child"),
            };
            fn contains_fft_prime(
                node: &crate::recursive_ir::RecursiveFftNodeIr,
                prime: usize,
            ) -> bool {
                match node {
                    crate::recursive_ir::RecursiveFftNodeIr::FftRader(rader) => {
                        rader.prime == prime
                    }
                    crate::recursive_ir::RecursiveFftNodeIr::CooleyTukey(cooley) => {
                        contains_fft_prime(&cooley.left, prime)
                            || contains_fft_prime(&cooley.right, prime)
                    }
                    _ => false,
                }
            }
            fn contains_direct_prime(
                node: &crate::recursive_ir::RecursiveFftNodeIr,
                prime: usize,
            ) -> bool {
                match node {
                    crate::recursive_ir::RecursiveFftNodeIr::DirectRader(direct) => {
                        direct.prime == prime
                    }
                    crate::recursive_ir::RecursiveFftNodeIr::CooleyTukey(cooley) => {
                        contains_direct_prime(&cooley.left, prime)
                            || contains_direct_prime(&cooley.right, prime)
                    }
                    _ => false,
                }
            }
            let convolution_root = &outer.forward_recursive().unwrap().root;
            assert!(contains_fft_prime(convolution_root, 47));
            assert!(!contains_direct_prime(convolution_root, 47));
        }
        let mut input = vec![Complex32::new(0.0, 0.0); length * batch_count];
        for batch in 0..batch_count {
            input[batch * length + 1] = Complex32::new(1.0, 0.0);
        }
        let spectrum = match context
            .execute_transform_f32(&forward, TransformInput32::Complex(&input))
            .unwrap()
        {
            TransformOutput32::Complex(values) => values,
            TransformOutput32::Real(_) => panic!("Vulkan device-capped N566 returned real output"),
        };
        let forward_error = spectrum
            .iter()
            .enumerate()
            .map(|(index, actual)| {
                let k = index % length;
                let angle = -std::f32::consts::TAU * k as f32 / length as f32;
                (actual.re - angle.cos()).hypot(actual.im - angle.sin())
            })
            .fold(0.0f32, f32::max);
        assert!(forward_error <= 4.0e-3);
        let restored = match context
            .execute_transform_f32(&inverse, TransformInput32::Complex(&spectrum))
            .unwrap()
        {
            TransformOutput32::Complex(values) => values,
            TransformOutput32::Real(_) => {
                panic!("Vulkan inverse device-capped N566 returned real output")
            }
        };
        let round_trip_error = restored
            .iter()
            .zip(&input)
            .map(|(actual, expected)| (*actual - *expected).norm_sqr().sqrt())
            .fold(0.0f32, f32::max);
        assert!(round_trip_error <= 4.0e-3);
    }

